import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
const pricing = fs.readFileSync('src/lib/vendorPricing.ts', 'utf8');
const sync = fs.readFileSync('src/lib/vendorPriceSync.ts', 'utf8');
const context = { exports: {}, require: () => { throw Error('unexpected import'); } };
vm.runInNewContext(ts.transpileModule(pricing, { compilerOptions: { module: ts.ModuleKind.CommonJS } }).outputText, context);
const resolver = context.exports;
const syncContext = { exports: {}, require: id => id === './vendorPricing' ? resolver : (() => { throw Error(id); })() };
vm.runInNewContext(ts.transpileModule(sync, { compilerOptions: { module: ts.ModuleKind.CommonJS } }).outputText, syncContext);
const { planAuthorizedVendorPriceUpdate: plan } = syncContext.exports;
const now = new Date('2026-11-21T18:00:00Z');
const p = { organizationId: 'tenant-a', productId: 'p1', vendorId: 'v1', pricingMode: 'fixed', dealerCost: 80, sellingPrice: 200, retailPrice: 250, targetMarginPercent: 50 };
const q = { organizationId: 'tenant-a', productId: 'p1', vendorId: 'v1', authorized: true, dealerCost: 100, retailPrice: 300, costVerifiedAt: now.toISOString(), retailVerifiedAt: now.toISOString() };
const run = (product=p, quote=q) => plan(product, quote, now, 3600000);
assert.equal(run().patch.our_price, 200, 'fixed price independent of cost and MSRP');
assert.equal(run().patch.cost, 100);
assert.equal(run({...p,pricingMode:'retail'}).patch.our_price,300);
assert.equal(run({...p,pricingMode:'margin'}).patch.our_price,200);
assert.equal(run({...p,pricingMode:'margin'}, {...q,dealerCost:120}).patch.our_price,240);
assert.equal(run({...p,pricingMode:'retail'}, {...q,retailVerifiedAt:'2026-11-20T00:00:00Z'}).patch.our_price,200);
assert.equal(run({...p,pricingMode:'margin'}, {...q,costVerifiedAt:'2026-11-20T00:00:00Z'}).patch.our_price,200);
assert.throws(() => run(p,{...q,authorized:false}), /not authorized/);
assert.throws(() => run(p,{...q,organizationId:'tenant-b'}), /not authorized/);
assert.throws(() => run(p,{...q,productId:'other'}), /not authorized/);
assert.throws(() => run(p,{...q,vendorId:'other'}), /not authorized/);
assert.equal(run(p,{...q,costVerifiedAt:null,retailVerifiedAt:null}).patch.our_price,200);
console.log('Vendor price sync preflight tests passed');
